"""The a = 1 available-source transfer on H1, generated by negative-binomial quantile mapping.

Same prediction as `build_available_average_candidate --pseudocount 20 --direct`; only the
cells differ. For each target, the canonical 400 H1 control cells are first transformed as
in h1_generation (factor re-aimed at their own pseudobulk, multiplicative scaling, gene-wise
integerization). Then every *sparse* gene (pooled control mean below SPARSE counts per cell)
is replaced by quantile mapping:

    source  y_cg ~ NB(mu_cg = N_c s_g,  phi_g)    s_g: this 400-cell sample's proportion
    target       ~ NB(mu'_cg = N_c q_g, phi_g)    q_g: the predicted proportion
    u_cg = F(y_cg - 1) + V * f(y_cg),  V ~ U(0, 1)   (randomized PIT; ties broken at random)
    new_cg = F'^{-1}(u_cg)

With q = s this returns y exactly, so unchanged cells stay unchanged. q_g is the predicted
profile itself (not re-aimed through the sample), so a gene the 400 cells never expressed
(s_g = 0, u uniform) is drawn afresh from the target NB: zeros can become counts.
phi_g is the method-of-moments dispersion across all H1 controls (library-scaled means).
Diagnostic: for sparse genes whose mean rises by at least 1.5x, zero fraction against mean per
cell in the H1 truth cells, the multiplicative cells and the quantile-mapped cells.
Run: pixi run python -m scripts.evaluation.build_quantile_mapping_candidate OUT.h5ad
"""

from __future__ import annotations

import argparse
import json
import zlib
from pathlib import Path

import anndata as ad
import numpy as np
import pandas as pd
from scipy import sparse
from scipy.stats import nbinom

import scripts.evaluation.h1_transfer_regression as reg
from scripts.evaluation.build_available_average_candidate import ANCHORS, H1, PHASE1
from scripts.evaluation.generate_h1_null_generators import dispersion
from scripts.evaluation.generate_replogle_h1_phase1 import CONTROLS, sha256
from scripts.evaluation.h1_generation import decode_lfc_genewise, expected_counts, harness_log
from scripts.evaluation.kolf_h1_transfer_rules import cpm
from scripts.linear_response.kernel import write_prediction

C = 20.0
SPARSE = 2.0  # counts per cell: below this, quantile mapping replaces multiplicative scaling
H1_FULL = reg.ROOT / "data/external/vcc2025_h1/adata_Training.h5ad"
REFERENCE = reg.ROOT / "reports/vcc2026-h1/reference_cells.csv"
REPORT = reg.ROOT / "reports/h1-transfer-regression/cell_eval_v3/available_avg_direct_c20_qmap"
BUDGET = 40_000_000  # CDF-table entries per chunk


def available_factor():
    with np.load(PHASE1) as a:
        targets, genes = a["target_gene"].astype(str), a["output_gene"].astype(str)
        rows = a["source_rows"].astype(int)
    with np.load(H1) as a:
        h0 = cpm(a["h1_control_count_sum"])
    ti = {t: i for i, t in enumerate(targets)}
    gi = {g: i for i, g in enumerate(genes)}
    total, count = np.zeros((len(targets), len(genes))), np.zeros((len(targets), len(genes)), dtype=int)
    for s in ANCHORS:
        with np.load(reg.SOURCE / f"available_{s}/{s}.npz") as z:
            r = np.array([ti[t] for t in z["targets"].astype(str)])
            g = np.array([gi[x] for x in z["genes"].astype(str)])
            change = reg.direction(z["source_perturbed"], z["source_control"], C)
        total[np.ix_(r, g)] += change
        count[np.ix_(r, g)] += 1
    d = np.divide(total, count, out=np.zeros_like(total), where=count > 0)
    pred = reg.realize(d, h0, C, 1.0)
    with np.errstate(divide="ignore", invalid="ignore"):
        factor = np.where(h0 > 0, np.log2(pred / h0), 0.0)
    return targets, genes, rows, np.where(np.isfinite(factor), factor, -60.0), pred / pred.sum(1, keepdims=True)


def nb_ppf(u, mu, r, max_steps=100_000):
    """Smallest k with NB-CDF(k) >= u, by the pmf recursion, over flat arrays."""
    k = np.zeros(u.shape, dtype=np.int64)
    pmf = np.exp(r * np.log(r / (r + mu)))
    cdf = pmf.copy()
    ratio = mu / (r + mu)
    live = np.flatnonzero(u > cdf)
    step = 0
    while live.size and step < max_steps:
        pmf[live] *= (step + r[live]) / (step + 1) * ratio[live]
        cdf[live] += pmf[live]
        k[live] += 1
        live = live[(u[live] > cdf[live]) & (pmf[live] > 1e-300)]
        step += 1
    return k


def quantile_map(y, n, s, q, phi, rng):
    """Map counts y (cells x genes) from NB(n s, phi) to NB(n q, phi) by randomized PIT."""
    r = np.broadcast_to(1.0 / phi[None, :], y.shape).ravel()
    mu = (n * s[None, :]).ravel()
    mu2 = (n * q[None, :]).ravel()
    yy = y.ravel()
    lo = np.zeros(yy.shape)
    hi = np.exp(r * np.log(r / (r + mu)))  # P(0)
    nz = np.flatnonzero(yy)
    prob = r[nz] / (r[nz] + mu[nz])
    lo[nz] = nbinom.cdf(yy[nz] - 1, r[nz], prob)
    hi[nz] = nbinom.cdf(yy[nz], r[nz], prob)
    u = np.minimum(lo + rng.random(yy.shape) * (hi - lo), 1 - 1e-12)
    return nb_ppf(u, mu2, r).reshape(y.shape)


def truth_blocks(targets):
    ref = pd.read_csv(REFERENCE)
    order = np.sort(ref.source_row.unique())
    h1 = ad.read_h5ad(H1_FULL, backed="r")
    X = sparse.csr_matrix(h1.X[order])
    h1.file.close()
    at = pd.Series(np.arange(len(order)), index=order)
    return {t: X[at[ref.loc[ref.target_gene == t, "source_row"]].to_numpy()] for t in targets}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("output")
    parser.add_argument("--null", action="store_true", help="no perturbation: the generator's null test")
    args = parser.parse_args()
    report = REPORT.with_name("qmap_null") if args.null else REPORT
    report.mkdir(parents=True, exist_ok=True)
    targets, genes, rows, factor, profile = available_factor()
    controls = ad.read_h5ad(CONTROLS)
    X = sparse.csr_matrix(controls.X).astype(np.float64)
    lib = np.asarray(X.sum(axis=1)).ravel()
    pooled_counts = np.asarray(X.sum(axis=0)).ravel()
    p = pooled_counts / pooled_counts.sum()
    per_cell = pooled_counts / X.shape[0]
    phi = dispersion(X, lib, lambda a, b: p[None, :])
    sparse_genes = np.flatnonzero((per_cell > 0) & (per_cell < SPARSE))
    band = (per_cell > 0.2) & (per_cell <= 1.0)
    pooled = cpm(pooled_counts)
    print(f"{len(sparse_genes)} sparse genes mapped; phi median {np.median(phi[sparse_genes]):.3f}", flush=True)
    if args.null:
        factor[:] = 0.0
        profile[:] = p
    truth = truth_blocks(targets)

    blocks, cos, diag = {}, [], []
    for k, t in enumerate(targets):
        raw = X[rows[k]].tocsr()
        sample_counts = np.asarray(raw.sum(axis=0)).ravel()
        with np.errstate(divide="ignore", invalid="ignore"):
            shift = np.where(sample_counts > 0, np.log2(pooled / cpm(sample_counts)), 0.0)
        lfc = factor[k] + np.where(np.isfinite(shift), shift, 0.0)
        rng = np.random.default_rng(zlib.crc32(f"qmap:{t}".encode()))
        mult = decode_lfc_genewise(raw, lfc, rng).toarray().astype(np.int64)
        expected = expected_counts(raw, lfc)
        y = raw.toarray().astype(np.int64)
        n = lib[rows[k]][:, None]
        s_g = y[:, sparse_genes].sum(0) / n.sum()
        q_g = profile[k, sparse_genes]  # includes genes the 400 cells never saw
        mapped = quantile_map(y[:, sparse_genes], n, s_g, q_g, phi[sparse_genes], rng)
        counts = mult.copy()
        counts[:, sparse_genes] = mapped
        blocks[t] = sparse.csr_matrix(counts.astype(np.int32))
        base = harness_log(sample_counts.astype(float))
        ideal = expected.sum(0)
        ideal[sparse_genes] = n.sum() * q_g
        want = harness_log(ideal) - base
        real = harness_log(counts.sum(0).astype(float)) - base
        cos.append(float(want @ real / (np.linalg.norm(want) * np.linalg.norm(real))))
        # zero fraction vs mean for band genes whose mean rises >= 1.5x
        tr = truth[t].toarray()
        ctrl_mean = y[:, band].mean(0)
        for label, block in (("truth", tr), ("multiplicative", mult), ("quantile_map", counts)):
            m = block[:, band].mean(0)
            up = m >= 1.5 * np.maximum(ctrl_mean, 1e-9)
            diag.append(pd.DataFrame({"generator": label, "target": t, "mean_per_cell": m[up],
                                      "zero_fraction": (block[:, band] == 0).mean(0)[up]}))
    write_prediction(blocks, genes.tolist(), Path(args.output))
    d = pd.concat(diag)
    d["mean_bin"] = pd.cut(d.mean_per_cell, [0, 0.5, 1, 2, 4, 1e9])
    curve = d.groupby(["mean_bin", "generator"], observed=True).zero_fraction.agg(["mean", "count"]).unstack("generator")
    curve.to_csv(report / "zero_fraction_vs_mean_increases.csv")
    summary = {"sparse_genes_mapped": len(sparse_genes), "fidelity_median_cosine": float(np.median(cos)),
               "prediction_sha256": sha256(Path(args.output))}
    (report / "generation.json").write_text(json.dumps(summary, indent=1))
    print(curve.round(3).to_string(), flush=True)
    print(json.dumps(summary), flush=True)


if __name__ == "__main__":
    main()
